<?php
declare(strict_types=1);
namespace DigiForge\Tests;
use PHPUnit\Framework\TestCase;
use DigiForge\POD\PrintifySupportContract as Contract;
require_once __DIR__.'/../../includes/POD/PrintifySupportContract.php';
final class PrintifySupportContractTest extends TestCase
{
 private function input():array{return ['order_id'=>'order_1','reason'=>'wrong_design','description'=>'Wrong side.','image_urls'=>['https://example.com/photo.png'],'line_items'=>[['line_item_id'=>'line_1','quantity'=>1]]];}
 private function item():array{return ['id'=>'request_1','order_id'=>'order_1','type'=>'order_refund','status'=>'processing','outcome'=>'unresolved','line_item_ids'=>['line_1'],'created_at'=>'2026-08-24 10:00:00+00:00','updated_at'=>'2026-08-24 10:00:00+00:00','status_details'=>'Private provider narrative'];}
 public function testOfficialPathsAndNumericQuantity():void {foreach(['SUPPORT_REPRINT'=>'reprint','SUPPORT_REFUND'=>'refund'] as $op=>$path){$r=Contract::prepare($op,'12',$this->input());self::assertSame('/v1/shops/12/orders/order_1/support-requests/'.$path,$r['endpoint']);self::assertSame(1,$r['body']['line_items'][0]['quantity']);self::assertSame('orders.write',$r['required_scope']);self::assertFalse($r['external_execution_authorized']);}}
 public function testListAndDetailEnvelopes():void {$item=$this->item();$r=Contract::prepare('SUPPORT_LIST','12',['order_id'=>'order_1']);$e=Contract::project($r,['data'=>[$item]],200);self::assertSame('pending',$e['support_requests'][0]['status']);self::assertSame('processing',$e['support_requests'][0]['source_status']);self::assertArrayNotHasKey('status_details',$e['support_requests'][0]);$r=Contract::prepare('SUPPORT_DETAIL','12',['order_id'=>'order_1','support_request_id'=>'request_1']);self::assertSame('request_1',Contract::project($r,['data'=>$item],200)['support_request']['id']);}
 public function testCreationAcknowledgesRequestWithoutRefundGuarantee():void {$r=Contract::prepare('SUPPORT_REFUND','12',$this->input());$e=Contract::project($r,$this->item(),201);self::assertSame('request_acknowledged',$e['result']);self::assertFalse($e['refund_guaranteed']);self::assertArrayNotHasKey('body',$e);}
 public function testAddressDiscriminatorAndPrivacy():void {$r=Contract::prepare('SUPPORT_ADDRESS_CHANGE','12',['order_id'=>'order_1','first_name'=>'Jane','last_name'=>'Smith','address1'=>'Street 1','city'=>'Retie','country'=>'BE','zip'=>'2470']);$e=Contract::project($r,['resolution'=>'updated_directly','order_id'=>'order_1','address_to'=>$r['body']],200);self::assertSame('address_updated',$e['result']);self::assertArrayNotHasKey('address_to',$e);$data=$this->item();unset($data['line_item_ids']);$data['type']='order_address_editing';$data['resolution']='support_request_created';self::assertSame('request_acknowledged',Contract::project($r,$data,201)['result']);}
 public function testUnknownFieldsRejected():void {$v=$this->input();$v['refund_amount']=100;$this->expectException(\InvalidArgumentException::class);Contract::prepare('SUPPORT_REFUND','12',$v);}
 public function testQuotedQuantityRejected():void {$v=$this->input();$v['line_items'][0]['quantity']='1';$this->expectException(\InvalidArgumentException::class);Contract::prepare('SUPPORT_REFUND','12',$v);}
 public function testPrivateImageUrlRejected():void {$v=$this->input();$v['image_urls']=['https://127.0.0.1/photo'];$this->expectException(\InvalidArgumentException::class);Contract::prepare('SUPPORT_REFUND','12',$v);}
 public function testUnsafeUrlVariantsRejected():void {foreach(['http://example.com/p','https://user@example.com/p','https://example.com/p#fragment','https://10.0.0.1/p','https://local.internal/p'] as $url){$v=$this->input();$v['image_urls']=[$url];try{Contract::prepare('SUPPORT_REFUND','12',$v);self::fail('Unsafe URL accepted');}catch(\InvalidArgumentException){self::assertTrue(true);}}}
 public function testUnknownOutcomeRejected():void {$r=Contract::prepare('SUPPORT_REFUND','12',$this->input());$v=$this->item();$v['outcome']='refunded';$this->expectException(\InvalidArgumentException::class);Contract::project($r,$v,201);}
 public function testOrderMismatchRejected():void {$r=Contract::prepare('SUPPORT_REFUND','12',$this->input());$v=$this->item();$v['order_id']='other';$this->expectException(\InvalidArgumentException::class);Contract::project($r,$v,201);}
 public function testProviderErrorsNeverCopyRawMessages():void {$r=Contract::prepare('SUPPORT_REFUND','12',$this->input());$e=Contract::project($r,['errors'=>['email'=>'private@example.com']],400);self::assertSame('validation_failed',$e['error_category']);self::assertArrayNotHasKey('errors',$e);self::assertSame('unknown_error',Contract::project($r,'raw private error',503)['error_category']);}
 public function testExactOrderLineEligibility():void {Contract::validateEligibility('SUPPORT_REFUND',$this->input(),['id'=>'order_1','line_items'=>[['id'=>'line_1','quantity'=>1]]]);self::assertTrue(true);$this->expectException(\InvalidArgumentException::class);Contract::validateEligibility('SUPPORT_REFUND',$this->input(),['id'=>'order_1','line_items'=>[['id'=>'other','quantity'=>1]]]);}
 public function testMissingLineIdentityFailsClosed():void {$this->expectException(\InvalidArgumentException::class);Contract::validateEligibility('SUPPORT_REPRINT',$this->input(),['id'=>'order_1','line_items'=>[['quantity'=>1]]]);}
}
